#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSupercyEngine: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = SupercyEngine

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> SupercyEngine {
        return SupercyEngine(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: SupercyEngine) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SupercyEngine {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: SupercyEngine, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSupercyEngine_lift(_ pointer: UnsafeMutableRawPointer) throws -> SupercyEngine {
    return try FfiConverterTypeSupercyEngine.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeSupercyEngine_lower(_ value: SupercyEngine) -> UnsafeMutableRawPointer {
    return FfiConverterTypeSupercyEngine.lower(value)
}




/**
 * A colour with straight alpha.
 */
public struct AnnotationColor {
    /**
     * Red.
     */
    public var r: UInt8
    /**
     * Green.
     */
    public var g: UInt8
    /**
     * Blue.
     */
    public var b: UInt8
    /**
     * Alpha (255 is opaque).
     */
    public var a: UInt8

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Red.
         */r: UInt8, 
        /**
         * Green.
         */g: UInt8, 
        /**
         * Blue.
         */b: UInt8, 
        /**
         * Alpha (255 is opaque).
         */a: UInt8) {
        self.r = r
        self.g = g
        self.b = b
        self.a = a
    }
}

#if compiler(>=6)
extension AnnotationColor: Sendable {}
#endif


extension AnnotationColor: Equatable, Hashable {
    public static func ==(lhs: AnnotationColor, rhs: AnnotationColor) -> Bool {
        if lhs.r != rhs.r {
            return false
        }
        if lhs.g != rhs.g {
            return false
        }
        if lhs.b != rhs.b {
            return false
        }
        if lhs.a != rhs.a {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(r)
        hasher.combine(g)
        hasher.combine(b)
        hasher.combine(a)
    }
}



