/**
 * The application in front when something was copied.
 */
public struct SourceApp {
    /**
     * Bundle identifier, such as `com.example.editor`.
     */
    public var bundleId: String
    /**
     * Display name.
     */
    public var name: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Bundle identifier, such as `com.example.editor`.
         */bundleId: String, 
        /**
         * Display name.
         */name: String) {
        self.bundleId = bundleId
        self.name = name
    }
}

#if compiler(>=6)
extension SourceApp: Sendable {}
#endif


extension SourceApp: Equatable, Hashable {
    public static func ==(lhs: SourceApp, rhs: SourceApp) -> Bool {
        if lhs.bundleId != rhs.bundleId {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(bundleId)
        hasher.combine(name)
    }
}



