// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * One edit.
 */

public enum AnnotationCommand {
    
    /**
     * Adds a shape on top.
     */
    case add(
        /**
         * What.
         */kind: AnnotationShapeKind, 
        /**
         * Style.
         */style: AnnotationStyle
    )
    /**
     * Moves shapes by (`dx`, `dy`) pixels.
     */
    case move(
        /**
         * The shapes.
         */ids: [UInt64], 
        /**
         * Horizontal offset.
         */dx: Float, 
        /**
         * Vertical offset.
         */dy: Float
    )
    /**
     * Drags a handle of a shape (not text or steps).
     */
    case resize(
        /**
         * The shape.
         */id: UInt64, 
        /**
         * The handle.
         */handle: ResizeHandle, 
        /**
         * Where it was dropped.
         */to: AnnotationPoint
    )
    /**
     * Restyles shapes.
     */
    case restyle(
        /**
         * The shapes.
         */ids: [UInt64], 
        /**
         * The new style.
         */style: AnnotationStyle
    )
    /**
     * Replaces the text and size of a text shape.
     */
    case editText(
        /**
         * The text shape.
         */id: UInt64, 
        /**
         * New text.
         */text: String, 
        /**
         * New font size in points.
         */fontSize: Float
    )
    /**
     * Deletes shapes.
     */
    case delete(
        /**
         * The shapes.
         */ids: [UInt64]
    )
    /**
     * Deletes every shape the eraser path touches.
     */
    case erase(
        /**
         * The path.
         */path: [AnnotationPoint], 
        /**
         * Eraser radius in points.
         */radius: Float
    )
    /**
     * Sets or clears the crop box.
     */
    case crop(
        /**
         * The crop box, or none for the whole image.
         */rect: AnnotationRect?
    )
    /**
     * Moves shapes above all others.
     */
    case bringToFront(
        /**
         * The shapes.
         */ids: [UInt64]
    )
    /**
     * Moves shapes below all others.
     */
    case sendToBack(
        /**
         * The shapes.
         */ids: [UInt64]
    )
}


