// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What a shape is and where it sits.
 */

public enum AnnotationShapeKind {
    
    /**
     * A rectangle.
     */
    case rect(
        /**
         * The box.
         */rect: AnnotationRect, 
        /**
         * Filled instead of outlined.
         */filled: Bool
    )
    /**
     * An ellipse in a box.
     */
    case ellipse(
        /**
         * The bounding box.
         */rect: AnnotationRect, 
        /**
         * Filled instead of outlined.
         */filled: Bool
    )
    /**
     * A straight line.
     */
    case line(
        /**
         * Start.
         */from: AnnotationPoint, 
        /**
         * End.
         */to: AnnotationPoint
    )
    /**
     * An arrow pointing at `to`.
     */
    case arrow(
        /**
         * Tail.
         */from: AnnotationPoint, 
        /**
         * Head.
         */to: AnnotationPoint
    )
    /**
     * A freehand stroke.
     */
    case pen(
        /**
         * Its points.
         */points: [AnnotationPoint]
    )
    /**
     * A highlighter stroke (multiply blend).
     */
    case highlighter(
        /**
         * Its points.
         */points: [AnnotationPoint]
    )
    /**
     * Text; `\n` starts a new line.
     */
    case text(
        /**
         * Top-left corner of the first line.
         */origin: AnnotationPoint, 
        /**
         * The text.
         */text: String, 
        /**
         * Font size in points.
         */fontSize: Float
    )
    /**
     * A numbered circle; the number is assigned when it is added.
     */
    case step(
        /**
         * Centre.
         */center: AnnotationPoint, 
        /**
         * The number.
         */number: UInt32
    )
    /**
     * Pixelation.
     */
    case mosaic(
        /**
         * The area.
         */rect: AnnotationRect, 
        /**
         * Block size in points.
         */block: UInt32
    )
    /**
     * Blur.
     */
    case blur(
        /**
         * The area.
         */rect: AnnotationRect, 
        /**
         * Radius in points.
         */radius: Float
    )
}


