        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .KeyMissing(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Locked(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .TooNew(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidSetting(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidPinKey(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidId(
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Keystore(
            message: try FfiConverterString.read(from: &buf)
            )
        case 9: return .PinsFile(
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SupercyError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .KeyMissing(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Locked(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
